function normalizeId(value: string | number) {
  if (typeof value === "number") return String(value);
  return value.trim();
}

type LoadState =
 | { status: "idle" }
 | { status: "loading" }
 | { status: "success"; tasks: string[] }
 | { status: "error"; message: string };
function label(state: LoadState) {
  if (state.status === "success") return `${state.tasks.length} tasks`;
  if (state.status === "error") return state.message;
  return state.status;
}

